grant select on b3_specimen to service_role;

select ok(not exists(select 1 from pg_proc where proname in ('read_life_climate_b3_source','reserve_life_climate_b3_intent','finalize_life_climate_b3_receipt') and prosecdef), 'B3 functions are SECURITY INVOKER');
select ok(not has_function_privilege('authenticated','public.reserve_life_climate_b3_intent(uuid,uuid,jsonb,text)','EXECUTE'), 'authenticated cannot reserve directly');
select ok(not has_function_privilege('anon','public.finalize_life_climate_b3_receipt(uuid,uuid,jsonb,jsonb,text)','EXECUTE'), 'anon cannot finalize');
select ok(not has_column_privilege('authenticated','public.life_climate_b3_intents','seed_safety','SELECT'), 'raw Seed safety source stays private');
select ok(not has_column_privilege('authenticated','public.life_climate_b3_intents','symbolic_input','SELECT'), 'raw birth source stays private');
select ok(not has_table_privilege('authenticated','public.life_climate_b3_intents','INSERT'), 'no browser intent writer');
select ok(not has_table_privilege('service_role','public.life_climate_b3_receipts','UPDATE'), 'no service receipt update');
select ok(not has_table_privilege('service_role','public.life_climate_b3_intents','DELETE'), 'no service intent delete');
select ok((select bool_and(relrowsecurity) from pg_class where oid in ('public.life_climate_b3_intents'::regclass,'public.life_climate_b3_receipts'::regclass)), 'both B3 ledgers enforce RLS');

set local role service_role;
select is(public.life_climate_b3_canonical_json('{"z":null,"a":[0.000001,1.230000,0,true,"中文😀"]}'::jsonb), '{"a":[0.000001,1.23,0,true,"中文😀"],"z":null}', 'JS canonical vector preserves six-place decimals, null, booleans, array order, Unicode');
select is(public.life_climate_b3_canonical_json('{"😀":1,"\uE000":2}'::jsonb), '{"":2,"😀":1}', 'object keys use Unicode codepoint order, not UTF16 or locale');
select throws_ok($$select public.life_climate_b3_canonical_json('0.0000001'::jsonb)$$,'P0001','b3_unsupported_precision','unsupported numeric precision never rounds');
select is(public.life_climate_b3_hash(value#>'{source,view}'),value#>>'{source,sourceContext}','SQL source hash equals real TypeScript fixture hash') from b3_specimen;
select ok(public.life_climate_b3_request_valid(value->'request'),'real TypeScript confirmed request passes SQL envelope checks') from b3_specimen;
select ok(not public.life_climate_b3_request_valid(jsonb_set(value->'request','{horizon}','null')),'JSON-null horizon fails closed') from b3_specimen;
select ok(not public.life_climate_b3_request_valid(jsonb_set(value->'request','{confirmation,pathIds}','["baseline","alternative-a"]')),'missing path confirmation fails closed') from b3_specimen;
select ok(public.life_climate_b3_bundle_valid(value->'source',value->'request',value->'run'),'actual engine-generated stock/flow specimen passes SQL evidence boundary') from b3_specimen;
select ok(not public.life_climate_b3_bundle_valid(value->'source',value->'request',jsonb_set(value->'run','{sourceSnapshot,binding,profileRevision}','999'))),'altered frozen source cannot finalize') from b3_specimen;
select ok(not public.life_climate_b3_bundle_valid(value->'source',value->'request',jsonb_set(value->'run','{events,4,causalEventIds}',jsonb_build_array(value#>'{run,events,0,id}')))),'cross-path predecessor fails even when its ID exists') from b3_specimen;
select ok(not public.life_climate_b3_bundle_valid(value->'source',value->'request',jsonb_set(value->'run','{events,0,causalEventIds}',jsonb_build_array(value#>'{run,events,1,id}')))),'future predecessor fails') from b3_specimen;
select ok(not public.life_climate_b3_bundle_valid(value->'source',value->'request',jsonb_set(value->'run','{claims,0,pathId}','"alternative-a"'))),'cross-path Claim evidence fails') from b3_specimen;
select ok(not public.life_climate_b3_bundle_valid(value->'source',value->'request',jsonb_set(value->'run','{claims,0,evidenceEventIds}','[]'))),'empty Claim evidence fails') from b3_specimen;
select ok(not public.life_climate_b3_bundle_valid(value->'source',value->'request',jsonb_set(value->'run','{paths,0,stages,0,stageIndex}','2'))),'stage order cannot be fabricated') from b3_specimen;
reset role;

insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
values
('00000000-0000-4000-8000-00000000b301','00000000-0000-0000-0000-000000000000','authenticated','authenticated','b3-owner-a@example.test','',now(),'{"provider":"email","providers":["email"]}','{}',now(),now()),
('00000000-0000-4000-8000-00000000b302','00000000-0000-0000-0000-000000000000','authenticated','authenticated','b3-owner-b@example.test','',now(),'{"provider":"email","providers":["email"]}','{}',now(),now());

set local role authenticated;
select set_config('request.jwt.claim.role','authenticated',true);
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-00000000b301',true);
select * from public.submit_seed_context_phase2('00000000-0000-4000-8000-00000000b311','{"trackType":"crossroad","timeWindow":"90_days","questionText":"A non-sensitive test situation","situationSummary":"A bounded test context for a local product flow.","recentEvents":"One routine update.","keyPeopleText":"No private details.","decisionOptions":"Compare two reasonable options.","worries":"Timing is uncertain.","forbiddenActions":"No unsafe action.","safetyBoundaries":"Keep the comparison conditional.","desiredOutput":"Show a bounded comparison.","privacyAck":true,"privacySafetyAck":true}'::jsonb);
insert into public.reality_profiles(user_id,seed_context_id,life_climate_classification,life_climate_evidence_summary,resources_classification,resources_evidence_summary,constraints_classification,constraints_evidence_summary)
select auth.uid(),id,'unknown','明确未知','unknown','明确未知','unknown','明确未知' from public.seed_contexts where user_id=auth.uid() and submission_key='00000000-0000-4000-8000-00000000b311';
reset role;

create temporary table b3_live(request jsonb,envelope jsonb) on commit drop;
grant select,insert,update on b3_live to service_role;
set local role service_role;
insert into b3_live(request)
select r||jsonb_build_object('confirmation',jsonb_build_object('context',public.life_climate_b3_hash(r),'assumptionIds','[]'::jsonb,'ruleIds','[]'::jsonb,'pathIds','["baseline","alternative-a","alternative-b"]'::jsonb,'reviewedSource',true))
from (select jsonb_build_object('version','life-climate-b3-v1','horizon','3_years','periodUnit','year','profileRevision',(s#>>'{source_snapshot,binding,profileRevision}')::integer,'sourceContext',s#>>'{source_snapshot,sourceContext}','model','{"resources":[],"assumptions":[],"constraintBindings":[],"commonRules":[],"alternatives":[{"id":"alternative-a","label":"备选甲","rules":[]},{"id":"alternative-b","label":"备选乙","rules":[]}]}'::jsonb,'symbolic','{"enabled":false}'::jsonb) r
  from (select public.read_life_climate_b3_source('00000000-0000-4000-8000-00000000b301') s) as source) as prepared;
update b3_live set envelope=public.reserve_life_climate_b3_intent('00000000-0000-4000-8000-00000000b301','00000000-0000-4000-8000-00000000b321',request,'b3-test');
select is(envelope->>'idempotent','false','first admission registers an immutable pending intent') from b3_live;
select is(envelope->'receipt','null'::jsonb,'pending admission has no invented completion') from b3_live;
select is((public.reserve_life_climate_b3_intent('00000000-0000-4000-8000-00000000b301','00000000-0000-4000-8000-00000000b321',request,'b3-test-replay')->'intent'),envelope->'intent','exact pending replay keeps its original clocks and inputs') from b3_live;
reset role;

set local role authenticated;
update public.reality_profiles set life_climate_value='本人更新的近况',life_climate_classification='fact',life_climate_evidence_summary='本人明确更新',revision=revision+1 where user_id=auth.uid();
reset role;
set local role service_role;
select is(public.reserve_life_climate_b3_intent('00000000-0000-4000-8000-00000000b301','00000000-0000-4000-8000-00000000b321',request,'b3-test-after-update')->'intent',envelope->'intent','historical recovery precedes changed current Profile') from b3_live;
select throws_ok($$select public.reserve_life_climate_b3_intent('00000000-0000-4000-8000-00000000b301','00000000-0000-4000-8000-00000000b321',jsonb_set(request,'{horizon}','"5_years"'),'b3-conflict') from b3_live$$,'P0001','idempotency_conflict','same key with changed original body conflicts before source reads');
select is(public.finalize_life_climate_b3_receipt('00000000-0000-4000-8000-00000000b301','00000000-0000-4000-8000-00000000b321',request,null,'safety_downgrade')#>>'{receipt,status}','rejected','authoritative refusal appends a terminal receipt with no generated result') from b3_live;
select is(public.reserve_life_climate_b3_intent('00000000-0000-4000-8000-00000000b301','00000000-0000-4000-8000-00000000b321',request,'b3-rejected-replay')#>>'{receipt,error_code}','safety_downgrade','a terminal rejection survives source changes and exact replay') from b3_live;
select throws_ok($$update public.life_climate_b3_intents set normalized_request='{}'$$,'42501',null,'service cannot rewrite frozen requests');
select throws_ok($$delete from public.life_climate_b3_receipts$$,'42501',null,'service cannot erase terminal receipts');
reset role;

set local role authenticated;
select is((select count(*)::integer from public.life_climate_b3_intents),1,'owner can discover original pending/terminal intent on another device');
select is((select count(*)::integer from public.life_climate_b3_receipts),1,'owner can discover original receipt');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-00000000b302',true);
select is((select count(*)::integer from public.life_climate_b3_intents),0,'another owner cannot read original requests');
select is((select count(*)::integer from public.life_climate_b3_receipts),0,'another owner cannot read receipt data');
select throws_ok($$select symbolic_input from public.life_climate_b3_intents$$,'42501',null,'raw birth column is not an owner browser permission');
reset role;
select * from finish();
rollback;
